CREATE COLUMN TABLE "TEST_AP"."OMRL" ("DocEntry" INTEGER CS_INT NOT NULL , "DocNum" INTEGER CS_INT NOT NULL , "Series" INTEGER CS_INT DEFAULT 0, "DocDate" LONGDATE CS_LONGDATE, "RevalType" NVARCHAR(1) DEFAULT 'P', "Handwrtten" NVARCHAR(1) DEFAULT 'N', "Printed" NVARCHAR(1) DEFAULT 'N', "Transfered" NVARCHAR(1) DEFAULT 'N', "DocCur" NVARCHAR(3), "DocRate" DECIMAL(21,6) CS_FIXED, "Ref2" NVARCHAR(11), "Comments" NVARCHAR(254), "JrnlMemo" NVARCHAR(50), "TransId" INTEGER CS_INT, "DocTime" SMALLINT CS_INT, "Confirmed" NVARCHAR(1) DEFAULT 'Y', "Instance" SMALLINT CS_INT DEFAULT 0 NOT NULL , "UpdateDate" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, "TaxDate" LONGDATE CS_LONGDATE, "DataSource" NVARCHAR(1) DEFAULT 'N', "StampNum" NVARCHAR(16), "FinncPriod" INTEGER CS_INT, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "StationID" INTEGER CS_INT, "Rounding" NVARCHAR(1) DEFAULT 'N', "Segment" SMALLINT CS_INT DEFAULT 0 NOT NULL , "ReqDate" LONGDATE CS_LONGDATE, "CancelDate" LONGDATE CS_LONGDATE, "Project" NVARCHAR(20), PRIMARY KEY ("DocEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OMRL_NUM" ON "TEST_AP"."OMRL" ( "DocNum" ASC, "Instance" ASC, "Segment" ASC );
CREATE INDEX "OMRL_SERIES" ON "TEST_AP"."OMRL" ( "Series" ASC )